import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int h = Integer.parseInt(st.nextToken());int totalWidth = 0;st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {int height = Integer.parseInt(st.nextToken());if (height > h) {totalWidth += 2;} else {totalWidth += 1;}}System.out.println(totalWidth);}}